from __future__ import annotations
from app.database_support import *

class DatabaseMixin5Part1:

    async def _ensure_contract_economy_schema_part_1(self, db: aiosqlite.Connection) -> None:
        await aiosqlite.execute_backend_ddl(db, sqlite_sql="\n                CREATE TABLE IF NOT EXISTS contracts (\n                    contract_id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    guild_id INTEGER NOT NULL,\n                    source_type TEXT NOT NULL,\n                    source_ref TEXT NOT NULL DEFAULT '',\n                    creator_id INTEGER,\n                    assignee_id INTEGER,\n                    title TEXT NOT NULL,\n                    reward_amount INTEGER NOT NULL,\n                    escrow_state TEXT NOT NULL DEFAULT 'held',\n                    escrow_wallet_amount INTEGER NOT NULL DEFAULT 0,\n                    escrow_bank_amount INTEGER NOT NULL DEFAULT 0,\n                    status TEXT NOT NULL DEFAULT 'open',\n                    created_at TEXT NOT NULL,\n                    expires_at TEXT NOT NULL,\n                    accepted_at TEXT,\n                    resolved_at TEXT\n                )\n            ", mysql_sql="\n                CREATE TABLE IF NOT EXISTS contracts (\n                    contract_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    source_type VARCHAR(24) NOT NULL,\n                    source_ref VARCHAR(64) NOT NULL DEFAULT '',\n                    creator_id BIGINT UNSIGNED NULL,\n                    assignee_id BIGINT UNSIGNED NULL,\n                    title VARCHAR(120) NOT NULL,\n                    reward_amount DECIMAL(65,0) NOT NULL,\n                    escrow_state VARCHAR(16) NOT NULL DEFAULT 'held',\n                    escrow_wallet_amount DECIMAL(65,0) NOT NULL DEFAULT 0,\n                    escrow_bank_amount DECIMAL(65,0) NOT NULL DEFAULT 0,\n                    status VARCHAR(16) NOT NULL DEFAULT 'open',\n                    created_at VARCHAR(64) NOT NULL,\n                    expires_at VARCHAR(64) NOT NULL,\n                    accepted_at VARCHAR(64) NULL,\n                    resolved_at VARCHAR(64) NULL,\n                    PRIMARY KEY (contract_id),\n                    KEY idx_contracts_active (guild_id,status,expires_at),\n                    KEY idx_contracts_assignee (guild_id,assignee_id,status,contract_id),\n                    KEY idx_contracts_creator (guild_id,creator_id,status,contract_id)\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ")
        await aiosqlite.execute_backend_ddl(db, sqlite_sql="\n                CREATE TABLE IF NOT EXISTS contract_objectives (\n                    objective_id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    contract_id INTEGER NOT NULL,\n                    guild_id INTEGER NOT NULL,\n                    objective_key TEXT NOT NULL,\n                    objective_type TEXT NOT NULL,\n                    target_ref TEXT NOT NULL,\n                    required_value INTEGER NOT NULL,\n                    current_value INTEGER NOT NULL DEFAULT 0,\n                    status TEXT NOT NULL DEFAULT 'pending',\n                    verification_mode TEXT NOT NULL DEFAULT 'domain_event',\n                    metadata_json TEXT NOT NULL DEFAULT '{}',\n                    created_at TEXT NOT NULL,\n                    updated_at TEXT NOT NULL,\n                    UNIQUE(contract_id,objective_key),\n                    FOREIGN KEY (contract_id) REFERENCES contracts(contract_id) ON DELETE CASCADE\n                )\n            ", mysql_sql="\n                CREATE TABLE IF NOT EXISTS contract_objectives (\n                    objective_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n                    contract_id BIGINT UNSIGNED NOT NULL,\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    objective_key VARCHAR(64) NOT NULL,\n                    objective_type VARCHAR(32) NOT NULL,\n                    target_ref VARCHAR(128) NOT NULL,\n                    required_value DECIMAL(65,0) NOT NULL,\n                    current_value DECIMAL(65,0) NOT NULL DEFAULT 0,\n                    status VARCHAR(16) NOT NULL DEFAULT 'pending',\n                    verification_mode VARCHAR(24) NOT NULL DEFAULT 'domain_event',\n                    metadata_json LONGTEXT NOT NULL,\n                    created_at VARCHAR(64) NOT NULL,\n                    updated_at VARCHAR(64) NOT NULL,\n                    PRIMARY KEY (objective_id),\n                    UNIQUE KEY uq_contract_objective_key (contract_id,objective_key),\n                    KEY idx_contract_objectives_active (guild_id,contract_id,status,objective_type,target_ref),\n                    CONSTRAINT fk_contract_objective_contract\n                        FOREIGN KEY (contract_id) REFERENCES contracts (contract_id)\n                        ON UPDATE CASCADE ON DELETE CASCADE\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ")
        await aiosqlite.execute_backend_ddl(db, sqlite_sql="\n                CREATE TABLE IF NOT EXISTS contract_events (\n                    event_id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    guild_id INTEGER NOT NULL,\n                    contract_id INTEGER NOT NULL,\n                    event_key TEXT NOT NULL,\n                    event_type TEXT NOT NULL,\n                    actor_id INTEGER NOT NULL,\n                    target_ref TEXT NOT NULL,\n                    delta INTEGER NOT NULL DEFAULT 1,\n                    payload_json TEXT NOT NULL DEFAULT '{}',\n                    created_at TEXT NOT NULL,\n                    UNIQUE(guild_id,contract_id,event_key),\n                    FOREIGN KEY (contract_id) REFERENCES contracts(contract_id) ON DELETE CASCADE\n                )\n            ", mysql_sql='\n                CREATE TABLE IF NOT EXISTS contract_events (\n                    event_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n                    guild_id BIGINT UNSIGNED NOT NULL,\n                    contract_id BIGINT UNSIGNED NOT NULL,\n                    event_key VARCHAR(160) NOT NULL,\n                    event_type VARCHAR(40) NOT NULL,\n                    actor_id BIGINT UNSIGNED NOT NULL,\n                    target_ref VARCHAR(128) NOT NULL,\n                    delta DECIMAL(65,0) NOT NULL DEFAULT 1,\n                    payload_json LONGTEXT NOT NULL,\n                    created_at VARCHAR(64) NOT NULL,\n                    PRIMARY KEY (event_id),\n                    UNIQUE KEY uq_contract_event_key (guild_id,contract_id,event_key),\n                    KEY idx_contract_events_contract (guild_id,contract_id,event_id),\n                    CONSTRAINT fk_contract_event_contract\n                        FOREIGN KEY (contract_id) REFERENCES contracts (contract_id)\n                        ON UPDATE CASCADE ON DELETE CASCADE\n                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci\n            ')
